import { computed, onScopeDispose, ref, shallowRef, watch } from 'vue';
import type { ParticipantPage } from './participantPages';

export type Collection<T> = { page: ParticipantPage<T>; total: number };
export type Choice = { id: string; name: string };
export const emptyCollection = <T>(): Collection<T> => ({
  page: { items: [], nextCursor: null, hasMore: false, isFirstPage: true, pageSize: 25 },
  total: 0,
});
export function record(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}
export function isChoice(value: unknown): value is Choice {
  return (
    record(value) &&
    typeof value.id === 'string' &&
    /^[0-7][0-9A-HJKMNP-TV-Z]{25}$/i.test(value.id) &&
    typeof value.name === 'string'
  );
}
export function isCollection<T>(
  value: unknown,
  row: (value: unknown) => value is T,
): value is Collection<T> {
  if (!record(value) || !record(value.page)) return false;
  const p = value.page;
  return (
    Number.isSafeInteger(value.total) &&
    (value.total as number) >= 0 &&
    Array.isArray(p.items) &&
    p.items.length <= 25 &&
    p.items.every(row) &&
    p.pageSize === 25 &&
    typeof p.isFirstPage === 'boolean' &&
    typeof p.hasMore === 'boolean' &&
    (p.nextCursor === null ||
      (typeof p.nextCursor === 'string' &&
        p.nextCursor.length > 0 &&
        p.nextCursor.length <= 4096)) &&
    p.hasMore === (p.nextCursor !== null)
  );
}

/** One bounded response per view; cancelled/stale replies cannot replace a newer principal's data. */
export function useTransferCollection<T>(
  initial: () => Collection<T>,
  scope: () => string,
  url: () => string,
  valid: (value: unknown) => value is T,
  fetcher: typeof fetch = fetch,
) {
  const current = shallowRef(initial());
  const busy = ref(false);
  const failed = ref(false);
  let active: AbortController | null = null;
  let generation = 0;
  let retryCursor: string | null = null;
  function invalidate(): void {
    generation++;
    active?.abort();
    active = null;
    busy.value = false;
    failed.value = false;
  }
  watch(
    [scope, initial],
    () => {
      invalidate();
      current.value = initial();
      retryCursor = null;
    },
    { flush: 'sync' },
  );
  onScopeDispose(invalidate);
  async function load(cursor: string | null = null): Promise<void> {
    invalidate();
    const request = ++generation;
    const requestScope = scope();
    active = new AbortController();
    retryCursor = cursor;
    busy.value = true;
    try {
      const endpoint = new URL(url(), 'http://transfer.invalid');
      if (cursor) endpoint.searchParams.set('cursor', cursor);
      const response = await fetcher(endpoint.pathname + endpoint.search, {
        headers: { Accept: 'application/json' },
        credentials: 'same-origin',
        signal: active.signal,
      });
      if (!response.ok) throw new Error('Transfer collection unavailable.');
      const data: unknown = await response.json();
      if (!isCollection(data, valid)) throw new Error('Invalid Transfer collection response.');
      if (request === generation && requestScope === scope()) current.value = data;
    } catch {
      if (request === generation && requestScope === scope()) failed.value = true;
    } finally {
      if (request === generation) {
        busy.value = false;
        active = null;
      }
    }
  }
  return { current, busy, failed, load, retry: () => load(retryCursor) };
}

export type ChoiceScope = {
  kind: 'windows' | 'cohorts' | 'members' | 'roster';
  scope: string;
  planId?: string | undefined;
  modelValue: string;
  selected?: Choice | null | undefined;
};

/** Current scoped options with an independently resolved off-page selection. */
export function useTransferChoices(input: () => ChoiceScope, fetcher: typeof fetch = fetch) {
  const search = ref('');
  const appliedSearch = ref('');
  const collection = shallowRef<Collection<Choice>>(emptyCollection());
  const selected = ref<Choice | null>(input().selected ?? null);
  const resolvedFor = ref<string | null>(null);
  const busy = ref(false);
  const failed = ref(false);
  const loaded = ref(false);
  let active: AbortController | null = null;
  let generation = 0;
  let retryPosition: { cursor: string | null; q: string } | null = null;
  const context = () => `${input().scope}|${input().planId ?? ''}|${input().kind}`;
  const offPage = computed(
    () =>
      Boolean(input().modelValue) &&
      !collection.value.page.items.some((row) => row.id === input().modelValue),
  );
  const currentSelection = computed(() => {
    const id = input().modelValue;
    if (resolvedFor.value === id) return selected.value?.id === id ? selected.value : null;
    if (selected.value?.id === id) return selected.value;
    return input().selected?.id === id ? (input().selected ?? null) : null;
  });
  function invalidate(): void {
    generation++;
    active?.abort();
    active = null;
    busy.value = false;
    failed.value = false;
  }
  watch(
    context,
    () => {
      invalidate();
      collection.value = emptyCollection();
      selected.value = null;
      resolvedFor.value = null;
      search.value = '';
      appliedSearch.value = '';
      loaded.value = false;
      retryPosition = null;
    },
    { flush: 'sync' },
  );
  watch(
    () => input().selected,
    (value) => {
      if (resolvedFor.value !== input().modelValue && value?.id === input().modelValue)
        selected.value = value;
    },
  );
  onScopeDispose(invalidate);
  async function request(cursor: string | null, q: string): Promise<void> {
    invalidate();
    const token = ++generation;
    const requestedContext = context();
    const chosen = input().modelValue;
    const params = new URLSearchParams({ q });
    if (input().planId) params.set('plan', input().planId!);
    if (cursor) params.set('cursor', cursor);
    if (chosen) params.set('selected', chosen);
    active = new AbortController();
    busy.value = true;
    retryPosition = { cursor, q };
    try {
      const response = await fetcher(
        `/alliance/transfers/manage/options/${input().kind}?${params}`,
        {
          headers: { Accept: 'application/json' },
          credentials: 'same-origin',
          signal: active.signal,
        },
      );
      if (!response.ok) throw new Error('Transfer choices unavailable.');
      const data: unknown = await response.json();
      const choice: unknown = record(data) ? data.selected : undefined;
      if (!isCollection(data, isChoice) || !(choice === null || isChoice(choice)))
        throw new Error('Invalid Transfer choices.');
      if (token !== generation || requestedContext !== context()) return;
      collection.value = { page: data.page, total: data.total };
      appliedSearch.value = q;
      loaded.value = true;
      if (input().modelValue === chosen) {
        selected.value = choice as Choice | null;
        resolvedFor.value = chosen;
      }
    } catch {
      if (token === generation && requestedContext === context()) failed.value = true;
    } finally {
      if (token === generation) {
        busy.value = false;
        active = null;
      }
    }
  }
  const load = (cursor: string | null = null) =>
    request(cursor, cursor === null ? search.value.trim() : appliedSearch.value);
  const retry = () =>
    retryPosition === null ? load() : request(retryPosition.cursor, retryPosition.q);
  function choose(id: string): void {
    // An off-page option can be retained, but a removed option cannot regain an old label.
    selected.value =
      collection.value.page.items.find((row) => row.id === id) ??
      (currentSelection.value?.id === id ? currentSelection.value : null);
    resolvedFor.value = id;
  }
  return {
    search,
    appliedSearch,
    collection,
    selected: currentSelection,
    offPage,
    busy,
    failed,
    loaded,
    load,
    retry,
    choose,
  };
}
